const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

export const BingoGeneratedProtobufCodec = {
  encode(typeName: string, value: unknown): Uint8Array {
    return encodeMessage(typeName, value as Record<string, unknown>);
  },
  decode(typeName: string, payload: Uint8Array): unknown {
    return decodeMessage(typeName, payload);
  }
};

function encodeMessage(typeName: string, value: Record<string, unknown>): Uint8Array {
  const fields = requireDescriptor(typeName);
  const chunks: Uint8Array[] = [];
  for (const field of fields) {
    const raw = value[field.name];
    if (raw === undefined || raw === null) continue;
    const values = field.repeated ? raw as readonly unknown[] : [raw];
    if (field.repeated && (field.kind === 'int32' || field.kind === 'uint64' || field.kind === 'bool')) {
      if (values.length > 0) {
        const packed = concatBytes(values.map((entry) => encodeScalarVarint(field.kind, entry)));
        chunks.push(encodeKey(field.number, 2), encodeLengthDelimited(packed));
      }
      continue;
    }
    for (const entry of values) {
      if (isDefaultScalar(field.kind, entry)) continue;
      if (field.kind === "int32" || field.kind === "uint64" || field.kind === "bool") {
        chunks.push(encodeKey(field.number, 0), encodeScalarVarint(field.kind, entry));
      } else {
        const bytes = field.kind === "string"
          ? textEncoder.encode(String(entry))
          : field.kind === "bytes"
            ? entry as Uint8Array
            : encodeMessage(field.kind.slice("message:".length), entry as Record<string, unknown>);
        chunks.push(encodeKey(field.number, 2), encodeLengthDelimited(bytes));
      }
    }
  }
  return concatBytes(chunks);
}

function decodeMessage(typeName: string, payload: Uint8Array): unknown {
  const fields = requireDescriptor(typeName);
  const byNumber = new Map(fields.map((field) => [field.number, field]));
  const value: Record<string, unknown> = Object.fromEntries(fields.map((field) => [field.name, defaultValue(field)]));
  let offset = 0;
  while (offset < payload.length) {
    const key = readVarint(payload, offset);
    offset = key.offset;
    const field = byNumber.get(Number(key.value >> 3n));
    const wireType = Number(key.value & 7n);
    if (field === undefined) {
      offset = skipField(payload, offset, wireType);
      continue;
    }
    if (wireType === 2) {
      const length = readVarint(payload, offset);
      const start = length.offset;
      const end = start + Number(length.value);
      if (end > payload.length) throw new Error("Generated Bingo Protobuf field exceeds payload length.");
      const bytes = payload.slice(start, end);
      offset = end;
      if (field.repeated && isVarintKind(field.kind)) {
        let packedOffset = 0;
        while (packedOffset < bytes.length) {
          const item = readVarint(bytes, packedOffset);
          (value[field.name] as unknown[]).push(decodeVarintValue(field.kind, item.value));
          packedOffset = item.offset;
        }
      } else {
        const decoded = field.kind === "string"
          ? textDecoder.decode(bytes)
          : field.kind === "bytes"
            ? bytes
            : decodeMessage(field.kind.slice("message:".length), bytes);
        assignDecoded(value, field, decoded);
      }
      continue;
    }
    if (wireType !== 0 || !isVarintKind(field.kind)) throw new Error("Generated Bingo Protobuf wire type is invalid.");
    const item = readVarint(payload, offset);
    offset = item.offset;
    assignDecoded(value, field, decodeVarintValue(field.kind, item.value));
  }
  const Constructor = (BingoGeneratedMessageConstructors as Partial<Record<string, new (values: never) => unknown>>)[typeName];
  if (Constructor === undefined) throw new Error(`Unknown generated Bingo Protobuf type: ${typeName}`);
  return new Constructor(value as never);
}

function requireDescriptor(typeName: string): readonly BingoFieldDescriptor[] {
  const descriptor = bingoDescriptors[typeName];
  if (descriptor === undefined) throw new Error(`Unknown generated Bingo Protobuf type: ${typeName}`);
  return descriptor;
}

function defaultValue(field: BingoFieldDescriptor): unknown {
  if (field.repeated) return [];
  if (field.optional || field.kind.startsWith("message:")) return null;
  if (field.kind === "string") return "";
  if (field.kind === "bool") return false;
  if (field.kind === "uint64") return "0";
  if (field.kind === "bytes") return new Uint8Array();
  return 0;
}

function assignDecoded(target: Record<string, unknown>, field: BingoFieldDescriptor, decoded: unknown): void {
  if (field.repeated) (target[field.name] as unknown[]).push(decoded);
  else target[field.name] = decoded;
}

function isVarintKind(kind: string): boolean {
  return kind === "int32" || kind === "uint64" || kind === "bool";
}

function isDefaultScalar(kind: string, value: unknown): boolean {
  return (kind === "string" && value === "") || (kind === "bool" && value === false)
    || (kind === "int32" && value === 0) || (kind === "uint64" && (value === "0" || value === 0));
}

function encodeScalarVarint(kind: string, value: unknown): Uint8Array {
  if (kind === "bool") return encodeVarint(value === true ? 1n : 0n);
  if (kind === "int32") return encodeVarint(BigInt.asUintN(64, BigInt(value as number)));
  return encodeVarint(BigInt(value as string | number | bigint));
}

function decodeVarintValue(kind: string, value: bigint): unknown {
  if (kind === "bool") return value !== 0n;
  if (kind === "int32") return Number(BigInt.asIntN(32, value));
  return value.toString();
}

function encodeKey(fieldNumber: number, wireType: number): Uint8Array {
  return encodeVarint(BigInt((fieldNumber << 3) | wireType));
}

function encodeLengthDelimited(payload: Uint8Array): Uint8Array {
  return concatBytes([encodeVarint(BigInt(payload.length)), payload]);
}

function encodeVarint(value: bigint): Uint8Array {
  const bytes: number[] = [];
  let remaining = value;
  do {
    const byte = Number(remaining & 0x7fn);
    remaining >>= 7n;
    bytes.push(remaining === 0n ? byte : byte | 0x80);
  } while (remaining !== 0n);
  return Uint8Array.from(bytes);
}

function readVarint(payload: Uint8Array, start: number): { readonly value: bigint; readonly offset: number } {
  let value = 0n;
  let shift = 0n;
  for (let offset = start; offset < payload.length && offset < start + 10; offset += 1) {
    const byte = payload[offset];
    value |= BigInt(byte & 0x7f) << shift;
    if ((byte & 0x80) === 0) return { value, offset: offset + 1 };
    shift += 7n;
  }
  throw new Error("Generated Bingo Protobuf varint is invalid.");
}

function skipField(payload: Uint8Array, offset: number, wireType: number): number {
  if (wireType === 0) return readVarint(payload, offset).offset;
  if (wireType === 2) {
    const length = readVarint(payload, offset);
    const end = length.offset + Number(length.value);
    if (end > payload.length) throw new Error("Generated Bingo Protobuf field exceeds payload length.");
    return end;
  }
  throw new Error(`Unsupported generated Bingo Protobuf wire type: ${wireType}`);
}

function concatBytes(chunks: readonly Uint8Array[]): Uint8Array {
  const result = new Uint8Array(chunks.reduce((total, chunk) => total + chunk.length, 0));
  let offset = 0;
  for (const chunk of chunks) { result.set(chunk, offset); offset += chunk.length; }
  return result;
}
